package com.bank.textblock;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class TextBlockTest {

    @Test void textBlockPreservesNewlines() {
        String tb = """
                A
                B
                C
                """;
        assertThat(tb).isEqualTo("A\nB\nC\n");
    }

    @Test void textBlockStripsCommonIndent() {
        String tb = """
                RELIANCE
                TCS
                """;
        assertThat(tb.lines().findFirst().orElse("")).isEqualTo("RELIANCE");
        // Common indent (16 spaces) stripped by compiler
    }

    @Test void textBlockNoEscapingForQuotes() {
        String json = """
                {"symbol": "RELIANCE"}
                """;
        assertThat(json).contains("\"symbol\"");  // natural quotes!
    }

    @Test void textBlockFormatted() {
        String result = """
                Hello, %s! Balance: Rs.%s
                """.formatted("Rajesh", "125000");
        assertThat(result).contains("Rajesh").contains("125000");
    }

    @Test void lineContinuation() {
        String joined = """
                first\
                second""";
        assertThat(joined).isEqualTo("firstsecond");  // \ joins lines
    }
}
