package com.bank.java8;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class TextBlockTest {

    @Test
    void multiLineJsonWithoutEscaping() {
        String json = """
                {
                  "from": "SAV2001",
                  "to": "CUR3001",
                  "amount": 50000
                }
                """;

        assertThat(json).contains("\"from\": \"SAV2001\"");
        assertThat(json.lines().count()).isEqualTo(6);   // incidental indent stripped
    }
}
